
const WORDS=[{"id": 0, "w": "领会", "p": "lǐnghuì", "t": "动词", "m": "hiểu thấu, lĩnh hội", "coll": "领会精神、深刻领会", "s": "认真阅读以后，她逐渐领会了这段文字所要表达的意思。"}, {"id": 1, "w": "内涵", "p": "nèihán", "t": "名词", "m": "nội hàm, ý nghĩa sâu bên trong", "coll": "丰富的内涵、文化内涵", "s": "了解作品的时代背景有助于读者理解其中丰富的文化内涵。"}, {"id": 2, "w": "港湾", "p": "gǎngwān", "t": "名词", "m": "vịnh cảng, bến cảng; nơi trú ngụ bình yên", "coll": "宁静的港湾、驶入港湾", "s": "黄昏时分，几艘小船缓缓驶入港湾结束了一天的航行。"}, {"id": 3, "w": "晴朗", "p": "qínglǎng", "t": "形容词", "m": "nắng ráo, trời quang", "coll": "天气晴朗、晴朗的天空", "s": "天气晴朗远处的山峰在阳光下显得格外清晰。"}, {"id": 4, "w": "清澈", "p": "qīngchè", "t": "形容词", "m": "trong suốt, trong veo", "coll": "河水清澈、清澈见底", "s": "山间的小河清澈见底水下的石子也能看得清清楚楚。"}, {"id": 5, "w": "出神", "p": "chūshén", "t": "动词", "m": "mải mê, đắm chìm, xuất thần", "coll": "听得出神、看得出神", "s": "老人讲起过去的故事孩子们听得出神。"}, {"id": 6, "w": "弦", "p": "xián", "t": "名词", "m": "dây đàn", "coll": "一根弦、琴弦", "s": "演奏之前，他仔细检查了琴上的每一根弦。"}, {"id": 7, "w": "美妙", "p": "měimiào", "t": "形容词", "m": "tuyệt vời, tươi đẹp", "coll": "美妙的音乐、美妙的感受", "s": "窗外传来一阵美妙的音乐让忙碌的人们暂时停下了脚步。"}, {"id": 8, "w": "砍伐", "p": "kǎnfá", "t": "动词", "m": "chặt, đốn", "coll": "砍伐树木、禁止砍伐", "s": "为了保护这片森林，当地对砍伐树木的行为作出了严格限制。"}, {"id": 9, "w": "平凡", "p": "píngfán", "t": "形容词", "m": "bình thường, tầm thường", "coll": "平凡的生活、平凡的人", "s": "这部作品记录了平凡的生活却让读者看到了普通人的坚持。"}, {"id": 10, "w": "乐谱", "p": "yuèpǔ", "t": "名词", "m": "bản nhạc, nhạc phổ", "coll": "一份乐谱、翻阅乐谱", "s": "她把乐谱放在架子上确认节奏以后才开始练习。"}, {"id": 11, "w": "赞叹", "p": "zàntàn", "t": "动词", "m": "ca ngợi, ca tụng", "coll": "赞叹不已、令人赞叹", "s": "看到这件精巧的作品，参观者不禁赞叹工匠技艺的高超。"}, {"id": 12, "w": "创作", "p": "chuàngzuò", "t": "动词", "m": "sáng tác, viết, soạn", "coll": "创作作品、进行创作", "s": "这位作家喜欢从生活中寻找材料把平常的小事融入自己的创作。"}, {"id": 13, "w": "民间", "p": "mínjiān", "t": "名词", "m": "dân gian", "coll": "民间故事、民间艺术", "s": "这项活动邀请当地艺人向学生介绍民间艺术的特点。"}, {"id": 14, "w": "精通", "p": "jīngtōng", "t": "动词", "m": "tinh thông, thông thạo", "coll": "精通语言、精通技艺", "s": "这位老师不仅精通多种语言也十分重视不同文化之间的交流。"}, {"id": 15, "w": "难能可贵", "p": "nánnéng kěguì", "t": "成语", "m": "đáng quý, quý hóa", "coll": "难能可贵、难能可贵的品质", "s": "面对困难，仍然愿意认真倾听别人是一种难能可贵的品质。"}, {"id": 16, "w": "应邀", "p": "yìngyāo", "t": "动词", "m": "nhận lời mời", "coll": "应邀参加、应邀出席", "s": "这位音乐家应邀来到学校与学生分享自己的学习经历。"}, {"id": 17, "w": "钦佩", "p": "qīnpèi", "t": "动词", "m": "kính trọng và khâm phục", "coll": "令人钦佩、深感钦佩", "s": "她多年坚持研究始终认真对待每一项任务令人钦佩。"}, {"id": 18, "w": "演奏", "p": "yǎnzòu", "t": "动词", "m": "diễn tấu", "coll": "演奏乐曲、现场演奏", "s": "音乐会开始后她为观众演奏了一首自己熟悉的乐曲。"}, {"id": 19, "w": "豪迈", "p": "háomài", "t": "形容词", "m": "hào hùng, phóng khoáng", "coll": "豪迈的气概、风格豪迈", "s": "这首诗语言有力表达了作者豪迈的胸怀。"}, {"id": 20, "w": "旋律", "p": "xuánlǜ", "t": "名词", "m": "giai điệu", "coll": "优美的旋律、熟悉的旋律", "s": "听到熟悉的旋律，他不禁想起了小时候在家乡生活的日子。"}, {"id": 21, "w": "雄伟", "p": "xióngwěi", "t": "形容词", "m": "hùng vĩ", "coll": "雄伟的建筑、山峰雄伟", "s": "站在广场上我们仰望着眼前雄伟的建筑。"}, {"id": 22, "w": "壮观", "p": "zhuàngguān", "t": "形容词", "m": "hùng tráng, nguy nga", "coll": "景象壮观、十分壮观", "s": "清晨云海在山间翻涌景象十分壮观让人久久不愿离开。"}, {"id": 23, "w": "气势", "p": "qìshì", "t": "名词", "m": "khí thế", "coll": "气势宏大、磅礴的气势", "s": "这幅画通过连绵的山峰表现出大自然磅礴的气势。"}, {"id": 24, "w": "气魄", "p": "qìpò", "t": "名词", "m": "khí phách", "coll": "非凡的气魄、宏大的气魄", "s": "这项跨越多年的工程展现了建设者非凡的气魄。"}, {"id": 25, "w": "曲折", "p": "qūzhé", "t": "形容词", "m": "uốn khúc, quanh co", "coll": "道路曲折、经历曲折", "s": "山里的道路十分曲折大家沿着指示牌慢慢前进。"}, {"id": 26, "w": "节奏", "p": "jiézòu", "t": "名词", "m": "nhịp điệu", "coll": "节奏明快、调整节奏", "s": "练习这段音乐时，老师先让学生找准基本的节奏。"}, {"id": 27, "w": "短促", "p": "duǎncù", "t": "形容词", "m": "ngắn ngủi, ngắn", "coll": "短促的声音、呼吸短促", "s": "门外响起几声短促的敲门声，随后又恢复了安静。"}, {"id": 28, "w": "波涛", "p": "bōtāo", "t": "名词", "m": "sóng cả, sóng lớn", "coll": "汹涌的波涛、波涛起伏", "s": "风渐渐大了海面上翻起层层波涛渔船也开始向港口返回。"}, {"id": 29, "w": "溅", "p": "jiàn", "t": "动词", "m": "tóe, bắn tóe", "coll": "水花飞溅、溅到身上", "s": "孩子踩进了浅浅的水坑水花溅到了裤脚上。"}, {"id": 30, "w": "气概", "p": "qìgài", "t": "名词", "m": "dũng khí, khí phách", "coll": "英雄气概、豪迈的气概", "s": "故事中的人物面对危险毫不退缩表现出令人敬佩的英雄气概。"}, {"id": 31, "w": "含义", "p": "hányì", "t": "名词", "m": "ý nghĩa, hàm nghĩa", "coll": "深刻的含义、词语的含义", "s": "讨论一个词语以前，我们应当先弄清楚它在句子中的具体含义。"}, {"id": 32, "w": "荒凉", "p": "huāngliáng", "t": "形容词", "m": "hoang vắng, hoang vu", "coll": "荒凉的山坡、显得荒凉", "s": "这片山坡过去十分荒凉经过多年的努力如今已经种满了树木。"}, {"id": 33, "w": "领悟", "p": "lǐngwù", "t": "动词", "m": "hiểu rõ, nhận thức rõ", "coll": "领悟道理、逐渐领悟", "s": "经过反复实践，他才逐渐领悟到老师当年那番话的道理。"}, {"id": 34, "w": "侃侃而谈", "p": "kǎnkǎn ér tán", "t": "成语", "m": "nói năng tự tin, ung dung và có lý lẽ", "coll": "侃侃而谈、围绕主题侃侃而谈", "s": "谈到自己熟悉的领域，她侃侃而谈清楚地说明了自己的观点。"}, {"id": 35, "w": "投机", "p": "tóujī", "t": "形容词", "m": "hợp ý, tâm đầu ý hợp (trong trò chuyện)", "coll": "谈得投机、十分投机", "s": "两人虽然第一次见面，却因为共同的兴趣谈得十分投机。"}, {"id": 36, "w": "黎明", "p": "límíng", "t": "名词", "m": "bình minh, rạng sáng", "coll": "黎明时分、迎接黎明", "s": "黎明时分，山谷里渐渐响起了鸟鸣新的一天开始了。"}, {"id": 37, "w": "告辞", "p": "gàocí", "t": "动词", "m": "cáo biệt, cáo từ", "coll": "起身告辞、向主人告辞", "s": "看看时间已经不早，客人们便起身告辞感谢主人的热情款待。"}, {"id": 38, "w": "黄昏", "p": "huánghūn", "t": "名词", "m": "hoàng hôn, lúc chạng vạng", "coll": "黄昏时分、接近黄昏", "s": "接近黄昏，湖边的游人渐渐散去水面也安静了下来。"}, {"id": 39, "w": "降临", "p": "jiànglín", "t": "动词", "m": "đến, tới, buông xuống", "coll": "夜幕降临、冬天降临", "s": "夜幕降临以后，街道两旁亮起了灯光行人也逐渐少了。"}, {"id": 40, "w": "沮丧", "p": "jǔsàng", "t": "形容词", "m": "chán nản, thất vọng", "coll": "感到沮丧、神情沮丧", "s": "第一次尝试没有成功让他有些沮丧，但朋友的鼓励使他重新振作起来。"}, {"id": 41, "w": "变故", "p": "biàngù", "t": "名词", "m": "biến cố, rủi ro, tai nạn", "coll": "家庭变故、突遭变故", "s": "由于家庭变故，她暂时中断学业后来才重新回到学校。"}, {"id": 42, "w": "逝世", "p": "shìshì", "t": "动词", "m": "từ trần, tạ thế", "coll": "因病逝世、逝世多年", "s": "这位作家虽然已经逝世多年他的作品仍然受到许多读者喜爱。"}, {"id": 43, "w": "坟墓", "p": "fénmù", "t": "名词", "m": "mồ mả", "coll": "一座坟墓、坟墓旁边", "s": "这篇散文记述了作者来到亲人坟墓旁追忆往事的情景。"}, {"id": 44, "w": "不止", "p": "bùzhǐ", "t": "动词", "m": "không dứt, không ngừng", "coll": "掌声不止、笑声不止", "s": "演出结束以后，观众席上掌声不止大家久久不愿离开。"}, {"id": 45, "w": "粉碎", "p": "fěnsuì", "t": "形容词／动词", "m": "vỡ vụn; đập tan, nghiền nát", "coll": "摔得粉碎、彻底粉碎", "s": "杯子不小心掉到地上摔得粉碎他只好仔细清理。"}, {"id": 46, "w": "向来", "p": "xiànglái", "t": "副词", "m": "từ trước đến nay, luôn luôn", "coll": "向来认真、向来如此", "s": "她做事向来认真即使时间紧张，也会仔细核对每一个细节。"}, {"id": 47, "w": "凄凉", "p": "qīliáng", "t": "形容词", "m": "thê lương", "coll": "凄凉的景象、感到凄凉", "s": "秋风里空荡荡的小院显得有些凄凉让人想起曾经热闹的日子。"}, {"id": 48, "w": "深情厚谊", "p": "shēnqíng hòuyì", "t": "成语", "m": "tình cảm sâu đậm", "coll": "深情厚谊、表达深情厚谊", "s": "这封信记录了两位朋友之间跨越多年的深情厚谊。"}, {"id": 49, "w": "真挚", "p": "zhēnzhì", "t": "形容词", "m": "chân thành tha thiết", "coll": "真挚的感情、真挚的祝福", "s": "离别的时候，同学们互相送上最真挚的祝福。"}, {"id": 50, "w": "纯洁", "p": "chúnjié", "t": "形容词", "m": "thuần khiết, trong sáng", "coll": "纯洁的友谊、心灵纯洁", "s": "共同学习的岁月让他们之间建立起了纯洁而深厚的友谊。"}];
