const group=g=>WORDS.slice(g*10,g===4?WORDS.length:g*10+10);
const groupOf=id=>Math.min(4,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/51 个词语。学完5组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),51)}<div class="ntc-progressgroups">${[0, 1, 2, 3, 4].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共51个词语，点击 ↗ 学习该词语',totalLearned()+'/51 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为五组：10、10、10、10、7个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===50;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<50){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:4,idx:10};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课51个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课51个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(51px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"2": [0, 8, 12], "5": [2, 6, 10], "8": [2, 6, 10], "11": [2, 6, 10], "14": [2, 6, 10], "17": [2, 6, 10], "20": [0, 8, 29], "23": [0, 8, 12], "26": [0, 8, 12], "29": [2, 6, 10], "32": [2, 6, 10], "35": [2, 6, 10], "38": [0, 8, 12], "41": [6, 10, 28], "44": [2, 6, 10], "47": [2, 6, 10], "50": [2, 6, 10]};
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的51个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第28课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第28课学习进度','第28课 · 51个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 51</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0, 1, 2, 3, 4].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK6 · 第28课';$('ntc-bookmark').textContent=student?total+'/51 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0, 1, 2, 3, 4].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0, 1, 2, 3, 4].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第28课学习进度</div><div style="padding:0 10px">'+total+'/51 个已学词语'+meter(total,51)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
const AUDIO_INDEX={"领会":"data:audio/mpeg;base64,","认真阅读以后，她逐渐领会了这段文字所要表达的意思。":"data:audio/mpeg;base64,","内涵":"data:audio/mpeg;base64,","了解作品的时代背景有助于读者理解其中丰富的文化内涵。":"data:audio/mpeg;base64,","港湾":"data:audio/mpeg;base64,","黄昏时分，几艘小船缓缓驶入港湾结束了一天的航行。":"data:audio/mpeg;base64,","晴朗":"data:audio/mpeg;base64,","天气晴朗远处的山峰在阳光下显得格外清晰。":"data:audio/mpeg;base64,","清澈":"data:audio/mpeg;base64,","山间的小河清澈见底水下的石子也能看得清清楚楚。":"data:audio/mpeg;base64,","出神":"data:audio/mpeg;base64,","老人讲起过去的故事孩子们听得出神。":"data:audio/mpeg;base64,","弦":"data:audio/mpeg;base64,","演奏之前，他仔细检查了琴上的每一根弦。":"data:audio/mpeg;base64,","美妙":"data:audio/mpeg;base64,","窗外传来一阵美妙的音乐让忙碌的人们暂时停下了脚步。":"data:audio/mpeg;base64,","砍伐":"data:audio/mpeg;base64,","为了保护这片森林，当地对砍伐树木的行为作出了严格限制。":"data:audio/mpeg;base64,","平凡":"data:audio/mpeg;base64,","这部作品记录了平凡的生活却让读者看到了普通人的坚持。":"data:audio/mpeg;base64,","乐谱":"data:audio/mpeg;base64,","她把乐谱放在架子上确认节奏以后才开始练习。":"data:audio/mpeg;base64,","赞叹":"data:audio/mpeg;base64,","看到这件精巧的作品，参观者不禁赞叹工匠技艺的高超。":"data:audio/mpeg;base64,","创作":"data:audio/mpeg;base64,","这位作家喜欢从生活中寻找材料把平常的小事融入自己的创作。":"data:audio/mpeg;base64,","民间":"data:audio/mpeg;base64,","这项活动邀请当地艺人向学生介绍民间艺术的特点。":"data:audio/mpeg;base64,","精通":"data:audio/mpeg;base64,","这位老师不仅精通多种语言也十分重视不同文化之间的交流。":"data:audio/mpeg;base64,","难能可贵":"data:audio/mpeg;base64,","面对困难，仍然愿意认真倾听别人是一种难能可贵的品质。":"data:audio/mpeg;base64,","应邀":"data:audio/mpeg;base64,","这位音乐家应邀来到学校与学生分享自己的学习经历。":"data:audio/mpeg;base64,","钦佩":"data:audio/mpeg;base64,","她多年坚持研究始终认真对待每一项任务令人钦佩。":"data:audio/mpeg;base64,","演奏":"data:audio/mpeg;base64,","音乐会开始后她为观众演奏了一首自己熟悉的乐曲。":"data:audio/mpeg;base64,","豪迈":"data:audio/mpeg;base64,","这首诗语言有力表达了作者豪迈的胸怀。":"data:audio/mpeg;base64,","旋律":"data:audio/mpeg;base64,","听到熟悉的旋律，他不禁想起了小时候在家乡生活的日子。":"data:audio/mpeg;base64,","雄伟":"data:audio/mpeg;base64,","站在广场上我们仰望着眼前雄伟的建筑。":"data:audio/mpeg;base64,","壮观":"data:audio/mpeg;base64,","清晨云海在山间翻涌景象十分壮观让人久久不愿离开。":"data:audio/mpeg;base64,","气势":"data:audio/mpeg;base64,","这幅画通过连绵的山峰表现出大自然磅礴的气势。":"data:audio/mpeg;base64,","气魄":"data:audio/mpeg;base64,","这项跨越多年的工程展现了建设者非凡的气魄。":"data:audio/mpeg;base64,","曲折":"data:audio/mpeg;base64,","山里的道路十分曲折大家沿着指示牌慢慢前进。":"data:audio/mpeg;base64,","节奏":"data:audio/mpeg;base64,","练习这段音乐时，老师先让学生找准基本的节奏。":"data:audio/mpeg;base64,","短促":"data:audio/mpeg;base64,","门外响起几声短促的敲门声，随后又恢复了安静。":"data:audio/mpeg;base64,","波涛":"data:audio/mpeg;base64,","风渐渐大了海面上翻起层层波涛渔船也开始向港口返回。":"data:audio/mpeg;base64,","溅":"data:audio/mpeg;base64,","孩子踩进了浅浅的水坑水花溅到了裤脚上。":"data:audio/mpeg;base64,","气概":"data:audio/mpeg;base64,","故事中的人物面对危险毫不退缩表现出令人敬佩的英雄气概。":"data:audio/mpeg;base64,","含义":"data:audio/mpeg;base64,","讨论一个词语以前，我们应当先弄清楚它在句子中的具体含义。":"data:audio/mpeg;base64,","荒凉":"data:audio/mpeg;base64,","这片山坡过去十分荒凉经过多年的努力如今已经种满了树木。":"data:audio/mpeg;base64,","领悟":"data:audio/mpeg;base64,","经过反复实践，他才逐渐领悟到老师当年那番话的道理。":"data:audio/mpeg;base64,","侃侃而谈":"data:audio/mpeg;base64,","谈到自己熟悉的领域，她侃侃而谈清楚地说明了自己的观点。":"data:audio/mpeg;base64,","投机":"data:audio/mpeg;base64,","两人虽然第一次见面，却因为共同的兴趣谈得十分投机。":"data:audio/mpeg;base64,","黎明":"data:audio/mpeg;base64,","黎明时分，山谷里渐渐响起了鸟鸣新的一天开始了。":"data:audio/mpeg;base64,","告辞":"data:audio/mpeg;base64,","看看时间已经不早，客人们便起身告辞感谢主人的热情款待。":"data:audio/mpeg;base64,","黄昏":"data:audio/mpeg;base64,","接近黄昏，湖边的游人渐渐散去水面也安静了下来。":"data:audio/mpeg;base64,","降临":"data:audio/mpeg;base64,","夜幕降临以后，街道两旁亮起了灯光行人也逐渐少了。":"data:audio/mpeg;base64,","沮丧":"data:audio/mpeg;base64,","第一次尝试没有成功让他有些沮丧，但朋友的鼓励使他重新振作起来。":"data:audio/mpeg;base64,","变故":"data:audio/mpeg;base64,","由于家庭变故，她暂时中断学业后来才重新回到学校。":"data:audio/mpeg;base64,","逝世":"data:audio/mpeg;base64,","这位作家虽然已经逝世多年他的作品仍然受到许多读者喜爱。":"data:audio/mpeg;base64,","坟墓":"data:audio/mpeg;base64,","这篇散文记述了作者来到亲人坟墓旁追忆往事的情景。":"data:audio/mpeg;base64,","不止":"data:audio/mpeg;base64,","演出结束以后，观众席上掌声不止大家久久不愿离开。":"data:audio/mpeg;base64,","粉碎":"data:audio/mpeg;base64,","杯子不小心掉到地上摔得粉碎他只好仔细清理。":"data:audio/mpeg;base64,","向来":"data:audio/mpeg;base64,","她做事向来认真即使时间紧张，也会仔细核对每一个细节。":"data:audio/mpeg;base64,","凄凉":"data:audio/mpeg;base64,","秋风里空荡荡的小院显得有些凄凉让人想起曾经热闹的日子。":"data:audio/mpeg;base64,","深情厚谊":"data:audio/mpeg;base64,","这封信记录了两位朋友之间跨越多年的深情厚谊。":"data:audio/mpeg;base64,","真挚":"data:audio/mpeg;base64,","离别的时候，同学们互相送上最真挚的祝福。":"data:audio/mpeg;base64,","纯洁":"data:audio/mpeg;base64,","共同学习的岁月让他们之间建立起了纯洁而深厚的友谊。":"data:audio/mpeg;base64,"};
function backup(){const content=JSON.stringify({format:'ntc-hsk6-bai28-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK6_Bai28_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk6-bai28-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=51)||!p.memory)throw Error();if(!confirm('恢复第28课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<51;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<5&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<51&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK6第28课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

